head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > maxlength]<br/>SearchBox 컴포넌트에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "스크립트로 setValue() 메소드를 사용하여 입력값을 설정하면 maxlength 가 적용되지 않고 전체 입력값이 저장됩니다.",
        "스크립트로 setValue() 후 포커스를 해제하거나 Enter 키 입력 시 maxlength 가 적용되어 초과분이 잘립니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {
    let rtn = target.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);
}



// target1 : maxlength=5, setValue 직후 (포커스 해제 전) → 전체 값 저장 확인
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("abcdefghij");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
};

// target2 : maxlength=5, setValue 후 blur → maxlength 적용으로 잘림
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("abcdefghij");
};

scwin.btn_blur2_onclick = function (e) {
    target2.render.blur();
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text(target2);
};
